public class WorkoutReportsActivity extends Activity {
 private final int BG=Color.rgb(8,18,31),PANEL=Color.rgb(18,39,59),GOLD=Color.rgb(235,190,76),BLUE=Color.rgb(45,145,245),TEAL=Color.rgb(40,205,190),GREEN=Color.rgb(70,215,135),WHITE=Color.WHITE,MUTED=Color.rgb(169,188,205);
 private final ArrayList<JSONObject> records=new ArrayList<>(); private File pendingFile;
 @Override public void onCreate(Bundle b){super.onCreate(b);JSONArray gps=WorkoutStore.getRunSessions(this),fartlek=WorkoutStore.getFartlekSessions(this);for(int i=0;i<gps.length();i++)if(gps.optJSONObject(i)!=null)records.add(gps.optJSONObject(i));for(int i=0;i<fartlek.length();i++)if(fartlek.optJSONObject(i)!=null)records.add(fartlek.optJSONObject(i));Collections.sort(records,(a,c)->Long.compare(c.optLong("startedAt",c.optLong("savedAt")),a.optLong("startedAt",a.optLong("savedAt"))));render();}
 private void render(){ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(24),dp(18),dp(28));root.setBackgroundColor(BG);sc.addView(root);TextView title=txt("RUNNING REPORTS",WHITE,22,true);root.addView(title);root.addView(txt("AUTO-GENERATED FROM WORKOUT HISTORY",TEAL,11,true));TextView note=txt("Every saved activity appears here automatically. Create or share a polished PDF from its recorded data.",MUTED,12,false);note.setPadding(0,dp(12),0,dp(14));root.addView(note);
 if(records.isEmpty()){root.addView(txt("NO ACTIVITIES RECORDED YET",GOLD,16,true));root.addView(txt("Save a GPS run or Fartlek session to generate your first report.",MUTED,13,false));} 
 for(JSONObject r:records){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(15),dp(14),dp(15),dp(14));card.setBackground(panel());LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(12);root.addView(card,cp);long t=r.optLong("startedAt",r.optLong("savedAt"));card.addView(txt(new SimpleDateFormat("EEE, dd MMM yyyy • HH:mm",Locale.getDefault()).format(new Date(t)),GOLD,12,true));card.addView(txt(r.optString("activityType",r.optString("type","RUN")).replace('_',' '),WHITE,19,true));double m=r.optDouble("distanceMeters");card.addView(txt(m>0?String.format(Locale.getDefault(),"%.2f km  •  %.2f mi",m/1000,m/1609.344):"Distance not recorded",TEAL,15,true));card.addView(txt("Duration "+clock(r.optInt("elapsedSeconds"))+"   |   Pace "+pace(r.optDouble("averagePaceSecondsPerKm")),MUTED,12,false));LinearLayout actions=new LinearLayout(this);Button save=button("SAVE PDF",BLUE),share=button("SHARE PDF",GREEN);actions.addView(save,new LinearLayout.LayoutParams(0,dp(46),1));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,dp(46),1);bp.leftMargin=dp(8);actions.addView(share,bp);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,-2);ap.topMargin=dp(12);card.addView(actions,ap);save.setOnClickListener(v->save(r));share.setOnClickListener(v->share(r));}
 setContentView(sc);}
 private void save(JSONObject r){File f=makePdf(r);if(f==null)return;pendingFile=f;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,fileName(r));startActivityForResult(i,41);}
 @Override protected void onActivityResult(int q,int result,Intent data){super.onActivityResult(q,result,data);if(q==41&&result==RESULT_OK&&data!=null&&data.getData()!=null&&pendingFile!=null)try(InputStream in=new FileInputStream(pendingFile);OutputStream out=getContentResolver().openOutputStream(data.getData())){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);msg("PDF saved.");}catch(Exception e){msg("Save failed: "+e.getMessage());}}
 private void share(JSONObject r){File f=makePdf(r);if(f==null)return;try{Uri u=FileProvider.getUriForFile(this,getPackageName()+".fileprovider",f);Intent i=new Intent(Intent.ACTION_SEND);i.setType("application/pdf");i.putExtra(Intent.EXTRA_STREAM,u);i.putExtra(Intent.EXTRA_SUBJECT,"Q-BOIX Running Report");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Share running report"));}catch(Exception e){msg("Share failed: "+e.getMessage());}}
 private File makePdf(JSONObject r){PdfDocument doc=new PdfDocument();int w=842,h=595;Canvas c=doc.startPage(new PdfDocument.PageInfo.Builder(w,h,1).create()).getCanvas();Paint p=new Paint(3);c.drawColor(BG);
 // Compact identity mark and report heading
 Bitmap logo=BitmapFactory.decodeResource(getResources(),R.drawable.qboix_asset_03);if(logo!=null){c.drawBitmap(Bitmap.createScaledBitmap(logo,42,42,true),30,20,p);logo.recycle();}
 p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));p.setColor(WHITE);p.setTextSize(23);c.drawText("Q-BOIX",82,47,p);p.setColor(TEAL);p.setTextSize(10);c.drawText("RUN PERFORMANCE REPORT",82,64,p);p.setColor(MUTED);p.setTextSize(10);c.drawText(r.optString("activityType",r.optString("type","RUN")).replace('_',' '),650,42,p);
 // Route map left with a deliberate soft fade on its right edge
 float mx=30,my=88,mw=360,mh=126;p.setColor(PANEL);c.drawRoundRect(mx,my,mx+mw,my+mh,13,13,p);drawRoute(c,p,r.optJSONArray("route"),mx+10,my+10,mw-20,mh-20);
 p.setShader(new LinearGradient(mx+mw-105,my,mx+mw-3,my, new int[]{Color.TRANSPARENT,BG},null,Shader.TileMode.CLAMP));c.drawRect(mx+mw-105,my,mx+mw,my+mh,p);p.setShader(null);
 p.setColor(WHITE);p.setTextSize(18);p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText("YOUR RUN",420,112,p);p.setColor(MUTED);p.setTextSize(11);long start=r.optLong("startedAt",r.optLong("savedAt"));long end=r.optLong("endedAt",r.optLong("savedAt",start));c.drawText(new SimpleDateFormat("EEEE, dd MMM yyyy",Locale.getDefault()).format(new Date(start)),420,134,p);c.drawText(new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(start))+" – "+new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(end)),420,152,p);c.drawText("GPS route preview • "+(r.optJSONArray("route")==null?0:r.optJSONArray("route").length())+" points",420,174,p);
 // One-line headline metrics
 double metres=r.optDouble("distanceMeters"),km=metres/1000.0,mi=metres/1609.344;int sec=r.optInt("elapsedSeconds");String[] vals={String.format(Locale.getDefault(),"%.2f km  /  %.2f mi",km,mi),clock(sec),pace(r.optDouble("averagePaceSecondsPerKm")),r.isNull("calories")?"Not recorded":String.valueOf(r.optInt("calories"))+" kcal"};String[] labs={"DISTANCE","TOTAL TIME","AVERAGE PACE","CALORIES BURNED"};
 for(int i=0;i<4;i++){float x=30+i*198;p.setColor(PANEL);c.drawRoundRect(x,230,x+188,288,10,10,p);p.setColor(GOLD);p.setTextSize(i==0?14:17);p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText(vals[i],x+11,255,p);p.setColor(MUTED);p.setTextSize(9);c.drawText(labs[i],x+11,275,p);}
 // Chart area: distance bars with pace line
 p.setColor(TEAL);p.setTextSize(12);p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText("PACE & DISTANCE COMPARISON",30,320,p);p.setColor(PANEL);c.drawRoundRect(30,332,420,492,10,10,p);drawChart(c,p,r,45,346,360,126);
 // Voice alert / split table
 p.setColor(TEAL);p.setTextSize(12);c.drawText("RUN DETAILS • ALERT SPLITS",445,320,p);p.setColor(PANEL);c.drawRoundRect(445,332,812,492,10,10,p);p.setColor(GOLD);p.setTextSize(9);c.drawText("DISTANCE",460,352,p);c.drawText("TIME",590,352,p);c.drawText("PACE",690,352,p);p.setColor(MUTED);c.drawText("Target alert: "+distance(r.optDouble("alertDistanceMeters")),460,370,p);
 JSONArray splits=r.optJSONArray("kilometreSplits"),laps=r.optJSONArray("lapSplits");JSONArray data=splits!=null&&splits.length()>0?splits:laps;int yy=391;if(data!=null&&data.length()>0){for(int i=0;i<data.length()&&i<4;i++){JSONObject s=data.optJSONObject(i);if(s==null)continue;double dm=s.optDouble("distanceMeters",1000);if(splits==data)dm=1000;int ss=s.optInt("splitSeconds");c.drawText(String.format(Locale.getDefault(),"%.2f km",dm/1000),460,yy,p);c.drawText(clock(ss),590,yy,p);c.drawText(pace(dm>0?ss/(dm/1000):0),690,yy,p);yy+=22;}}else c.drawText("No split intervals recorded",460,400,p);
 // Footer / event details
 p.setColor(GOLD);p.setTextSize(10);c.drawText("EVENT DETAILS",30,526,p);p.setColor(MUTED);p.setTextSize(9);c.drawText("Start: "+new SimpleDateFormat("dd MMM yyyy • HH:mm:ss",Locale.getDefault()).format(new Date(start)),30,544,p);c.drawText("Finish: "+new SimpleDateFormat("dd MMM yyyy • HH:mm:ss",Locale.getDefault()).format(new Date(end)),30,559,p);
 JSONArray route=r.optJSONArray("route");String loc="Location: GPS route captured";if(route!=null&&route.length()>0){JSONObject first=route.optJSONObject(0);if(first!=null)loc=String.format(Locale.US,"GPS start: %.5f, %.5f",first.optDouble("lat"),first.optDouble("lon"));}p.setColor(MUTED);c.drawText(loc,420,544,p);c.setColor(TEAL);c.drawText("Q-BOIX  •  Generated from saved Workout History  •  Unrecorded values are not estimated",420,559,p);
 doc.finishPage(doc.getPages().get(0));File dir=new File(getExternalFilesDir(android.os.Environment.DIRECTORY_DOCUMENTS),"Q-BOIX Reports");if(!dir.exists())dir.mkdirs();File f=new File(dir,fileName(r));try(FileOutputStream out=new FileOutputStream(f)){doc.writeTo(out);doc.close();return f;}catch(Exception e){doc.close();msg("PDF generation failed: "+e.getMessage());return null;}}
 private void drawRoute(Canvas c,Paint p,JSONArray a,float x,float y,float w,float h){if(a==null||a.length()<2){p.setColor(MUTED);p.setTextSize(12);c.drawText("GPS route unavailable",x+12,y+h/2,p);return;}double minA=90,maxA=-90,minO=180,maxO=-180;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null){minA=Math.min(minA,o.optDouble("lat"));maxA=Math.max(maxA,o.optDouble("lat"));minO=Math.min(minO,o.optDouble("lon"));maxO=Math.max(maxO,o.optDouble("lon"));}}Path path=new Path();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;float px=x+8+(float)((o.optDouble("lon")-minO)/Math.max(1e-7,maxO-minO))*(w-16),py=y+h-8-(float)((o.optDouble("lat")-minA)/Math.max(1e-7,maxA-minA))*(h-16);if(i==0)path.moveTo(px,py);else path.lineTo(px,py);}p.setColor(BLUE);p.setStrokeWidth(3);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);}
 private void drawChart(Canvas c,Paint p,JSONObject r,float x,float y,float w,float h){JSONArray a=r.optJSONArray("kilometreSplits");if(a==null||a.length()==0)a=r.optJSONArray("lapSplits");if(a==null||a.length()==0){p.setColor(MUTED);p.setTextSize(11);c.drawText("Split data will appear after a run records kilometre or lap splits.",x,y+h/2,p);return;}float base=y+h-15,barW=Math.min(34,(w-20)/a.length()-8);double max=1;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null)max=Math.max(max,o.optDouble("splitSeconds"));}Path paceLine=new Path();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;float cx=x+15+i*(w-30)/Math.max(1,a.length()-1);float bh=(float)(o.optDouble("splitSeconds")/max*(h-40));p.setColor(BLUE);c.drawRoundRect(cx-barW/2,base-bh,cx+barW/2,base,5,5,p);float py=y+10+(float)(o.optDouble("splitSeconds")/max*(h-38));if(i==0)paceLine.moveTo(cx,py);else paceLine.lineTo(cx,py);p.setColor(MUTED);p.setTextSize(8);c.drawText(""+(i+1),cx-3,base+11,p);}p.setColor(GOLD);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2.5f);c.drawPath(paceLine,p);p.setStyle(Paint.Style.FILL);p.setColor(MUTED);p.setTextSize(8);c.drawText("Blue bars: split duration   •   Gold line: pace trend",x,y+8,p);}
 private String distance(double m){return m<=0?"Not set":m>=1000?String.format(Locale.getDefault(),"%.2f km",m/1000):((int)m)+" m";}
 private String fileName(JSONObject o){return "Q-BOIX-Run-"+o.optLong("savedAt")+".pdf";}private String clock(int s){return String.format(Locale.getDefault(),"%02d:%02d:%02d",s/3600,(s%3600)/60,s%60);}private String pace(double s){return s<=0?"N/A":String.format(Locale.getDefault(),"%d:%02d /km",(int)(s/60),(int)Math.round(s)%60);}
 private TextView txt(String s,int c,int z,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextColor(c);t.setTextSize(z);if(b)t.setTypeface(null,1);return t;}private Button button(String s,int c){Button b=new Button(this);b.setText(s);b.setTextColor(WHITE);b.setTextSize(11);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(c));return b;}private android.graphics.drawable.GradientDrawable panel(){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(PANEL);d.setCornerRadius(dp(14));return d;}private int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}private void msg(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("OK",null).show();}
}